import{_ as f,a0 as s,w as p,s as o,ao as d,I as l,x as i,a1 as a,A as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"如何用四個簡單的步驟加速 LibreOffice | LCTT x X-CMD","titleTemplate":false,"description":"如何用四個簡單的步驟加速 LibreOffice | LCTT (201609) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何用四個簡單的步驟加速 LibreOffice | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何用四個簡單的步驟加速 LibreOffice | LCTT (201609) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201609/20160914 How to Speed Up LibreOffice with 4 Simple Steps","title":"如何用四個簡單的步驟加速 LibreOffice","tag":"201609","desc":""},"relativePath":"201609/20160914 How to Speed Up LibreOffice with 4 Simple Steps.md","filePath":"[post].md"}'),n={name:"201609/20160914 How to Speed Up LibreOffice with 4 Simple Steps.md"};function c(b,e,m,h,u,L){const t=s("Link");return p(),o("div",null,[e[13]||(e[13]=d('<h1 id="如何用四個簡單的步驟加速-libreoffice" tabindex="-1">如何用四個簡單的步驟加速 LibreOffice <a class="header-anchor" href="#如何用四個簡單的步驟加速-libreoffice" aria-label="Permalink to “如何用四個簡單的步驟加速 LibreOffice”">​</a></h1><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2016/08/speed-up-libreoffice-featured-2.jpg" alt=""></p><p>對於許多許多開源軟件的粉絲和支持者來説，LibreOffice 是 Microsoft Office 最好的替代品，在最近的一些發佈版本中可以看到它明顯有了巨大的改進。然而，初始啓動的體驗仍然距離期望有所距離。有一些方法可以縮短 LibreOffice 的啓動時間並改善它的整體性能。</p><p>在下面的段落裏，我將會展示一些實用性的步驟，你可以通過它們來改善 LibreOffice 的加載時間和響應能力。</p><h3 id="_1-增加每個對象和圖像緩存的內存佔用" tabindex="-1">1. 增加每個對象和圖像緩存的內存佔用 <a class="header-anchor" href="#_1-增加每個對象和圖像緩存的內存佔用" aria-label="Permalink to “1. 增加每個對象和圖像緩存的內存佔用”">​</a></h3><p>這將可以通過分配更多的內存資源給圖像緩存和對象來加快程序的加載時間。</p><ol><li>啓動 LibreOffice Writer (或者 Calc)。</li><li>點擊菜單欄上的 “工具 -&gt; 選項” 或者按鍵盤上的快捷鍵“Alt + F12”。</li><li>點擊 LibreOffice 下面的“內存”然後增加“用於 LibreOffice” 到 128MB。</li><li>同樣的增加“每個對象的內存佔用”到 20MB。</li><li>點擊確定來保存你的修改。</li></ol><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2016/08/speed-up-libreoffice-step-1.png" alt=""></p><p>注意：你可以根據自己機器的性能把數值設置得比建議值的高一些或低一些。最好通過親自體驗來看看什麼值能夠讓機器達到最佳性能。</p><h3 id="_2-啓用-libreoffice-的快速啓動器-quickstarter" tabindex="-1">2.啓用 LibreOffice 的快速啓動器（QuickStarter） <a class="header-anchor" href="#_2-啓用-libreoffice-的快速啓動器-quickstarter" aria-label="Permalink to “2.啓用 LibreOffice 的快速啓動器（QuickStarter）”">​</a></h3><p>如果你的機器上有足夠大的內存，比如 4GB 或者更大，你可以啓用“系統托盤快速啓動器”，從而讓 LibreOffice 的一部分保持在內存中，在打開新文件時能夠快速反應。</p><p>在啓用這個選擇以後，你會清楚的看到在打開新文件時它的性能有了很大的提高。</p><ol><li>通過點擊“工具 -&gt; 選項”來打開選項對話框。</li><li>在 “LibreOffice” 下面的側邊欄選擇“內存”。</li><li>勾選“啓用系統托盤快速啓動器”複選框。</li><li>點擊“確定”來保存修改。</li></ol><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2016/08/speed-up-libreoffice-2.png" alt=""></p><p>一旦這個選項啓用以後，你將會在你的系統托盤看到 LibreOffice 圖標，以及可以打開任何類型的文件的選項。</p><h3 id="_3-禁用-java-運行環境" tabindex="-1">3. 禁用 Java 運行環境 <a class="header-anchor" href="#_3-禁用-java-運行環境" aria-label="Permalink to “3. 禁用 Java 運行環境”">​</a></h3><p>另一個加快 LibreOffice 加載時間和響應能力的簡單方法是禁用 Java。</p><ol><li>同時按下“Alt + F12”打開選項對話框。</li><li>在側邊欄裏，選擇“Libreoffice”，然後選擇“高級”。</li><li>取消勾選“使用 Java 運行環境”選項。</li><li>點擊“確定”來關閉對話框。</li></ol><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2016/08/speed-up-libreoffice-3.png" alt=""></p><p>如果你只使用 Writer 和 Calc，那麼關閉 Java 不會影響你正常使用，但如果你需要使用 LibreOffice Base 和一些其他的特性，那麼你可能需要重新啓用它。在那種情況，將會彈出一個框詢問你是否希望再次打開它。</p><h3 id="_4-減少使用撤銷步驟" tabindex="-1">4. 減少使用撤銷步驟 <a class="header-anchor" href="#_4-減少使用撤銷步驟" aria-label="Permalink to “4. 減少使用撤銷步驟”">​</a></h3><p>默認情況下，LibreOffice 允許你撤銷一個文件的多達 100 個改變。絕大多數用户不需要這麼多，所以在內存中保留這麼多撤銷步驟是對資源的巨大浪費。</p><p>我建議減少撤銷步驟到 20 次以下來為其他東西釋放內存，但是這個部分需要根據你自己的需求來確定。</p><ol><li>通過點擊 “工具 -&gt; 選項”來打開選項對話框。</li><li>在 “LibreOffice” 下面的側邊欄，選擇“內存”。</li><li>在“撤銷”下面把步驟數目改成最適合你的值。</li><li>點擊“確定”來保存修改。</li></ol><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2016/08/speed-up-libreoffice-5.png" alt=""></p><p>假如你這些技巧為加速你的 LibreOffice 套件的加載時間提供了幫助，請在評論裏告訴我們。同樣，請分享你知道的任何其他技巧來給其他人帶來幫助。</p><hr>',27)),l("p",null,[e[1]||(e[1]=i("via: ",-1)),a(t,{href:"https://www.maketecheasier.com/speed-up-libreoffice/"},{default:r(()=>[...e[0]||(e[0]=[i("https://www.maketecheasier.com/speed-up-libreoffice/",-1)])]),_:1})]),l("p",null,[e[5]||(e[5]=i("作者：",-1)),a(t,{href:"https://www.maketecheasier.com/author/ayoisaiah/"},{default:r(()=>[...e[2]||(e[2]=[i("Ayo Isaiah",-1)])]),_:1}),e[6]||(e[6]=i(" 譯者：",-1)),a(t,{href:"https://github.com/ucasFL"},{default:r(()=>[...e[3]||(e[3]=[i("ucasFL",-1)])]),_:1}),e[7]||(e[7]=i(" 校對：",-1)),a(t,{href:"https://github.com/wxy"},{default:r(()=>[...e[4]||(e[4]=[i("wxy",-1)])]),_:1})]),l("p",null,[e[10]||(e[10]=i("本文由 ",-1)),a(t,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...e[8]||(e[8]=[i("LCTT",-1)])]),_:1}),e[11]||(e[11]=i(" 原創編譯，",-1)),a(t,{href:"https://linux.cn/"},{default:r(()=>[...e[9]||(e[9]=[i("Linux中國",-1)])]),_:1}),e[12]||(e[12]=i(" 榮譽推出",-1))])])}const T=f(n,[["render",c]]);export{x as __pageData,T as default};
